describe('Icon Button Accessibility', () => {
  beforeEach(() => {
    cy.visit('/icon-buttons');
  });

  it('should assign accessible names to all icon buttons', () => {
    // Verify each icon button has an accessible name
    cy.get('[data-testid="search-icon-button"]').should('have.attr', 'aria-label');
    cy.get('[data-testid="settings-icon-button"]').should('have.attr', 'aria-label');
    cy.get('[data-testid="notifications-icon-button"]').should('have.attr', 'aria-label');
    cy.get('[data-testid="profile-icon-button"]').should('have.attr', 'aria-label');

    // Verify accessible names are descriptive
    cy.get('[data-testid="search-icon-button"]').should('have.attr', 'aria-label', 'Search');
    cy.get('[data-testid="settings-icon-button"]').should('have.attr', 'aria-label', 'Settings');
    cy.get('[data-testid="notifications-icon-button"]').should('have.attr', 'aria-label', 'Notifications');
    cy.get('[data-testid="profile-icon-button"]').should('have.attr', 'aria-label', 'User Profile');

    // Verify buttons are focusable
    cy.get('[data-testid="search-icon-button"]').should('be.focusable');
    cy.get('[data-testid="settings-icon-button"]').should('be.focusable');
    cy.get('[data-testid="notifications-icon-button"]').should('be.focusable');
    cy.get('[data-testid="profile-icon-button"]').should('be.focusable');
  });

  it('should handle edge case of empty or missing accessible names', () => {
    // Verify that buttons without aria-label have fallback text or are disabled
    cy.get('[data-testid="empty-icon-button"]').should('have.attr', 'aria-label', 'Empty State');
    cy.get('[data-testid="disabled-icon-button"]').should('have.attr', 'aria-disabled', 'true');
    cy.get('[data-testid="disabled-icon-button"]').should('not.have.attr', 'aria-label');

    // Verify that disabled buttons are not interactive
    cy.get('[data-testid="disabled-icon-button"]').should('not.be.enabled');

    // Verify that all buttons have a role attribute
    cy.get('[data-testid="search-icon-button"]').should('have.attr', 'role', 'button');
    cy.get('[data-testid="settings-icon-button"]').should('have.attr', 'role', 'button');
  });
});
